insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('MATH','Linear equations','If 5x − 7 = 18, what is x?','[{"id": "A", "text": "3"}, {"id": "B", "text": "4"}, {"id": "C", "text": "5"}, {"id": "D", "text": "6"}]','C','Add 7 to both sides to get 5x = 25; divide by 5.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('MATH','Percentages','What is 20% of 150?','[{"id": "A", "text": "15"}, {"id": "B", "text": "25"}, {"id": "C", "text": "30"}, {"id": "D", "text": "35"}]','C','0.20 × 150 = 30.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('MATH','Functions','If f(x) = 2x² + 1, what is f(3)?','[{"id": "A", "text": "13"}, {"id": "B", "text": "18"}, {"id": "C", "text": "19"}, {"id": "D", "text": "20"}]','C','2(3²)+1 = 19.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('MATH','Geometry','A rectangle has length 8 and width 5. What is its area?','[{"id": "A", "text": "13"}, {"id": "B", "text": "26"}, {"id": "C", "text": "40"}, {"id": "D", "text": "80"}]','C','Area = length × width = 40.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('ENGLISH','Subject-verb agreement','Choose the grammatically correct sentence.','[{"id": "A", "text": "The list of items are long."}, {"id": "B", "text": "The list of items is long."}, {"id": "C", "text": "The list of items be long."}, {"id": "D", "text": "The list of items were long."}]','B','The subject is singular: list. Use is.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('ENGLISH','Punctuation','Which sentence uses a comma to set off the introductory phrase without splitting the main clause?','[{"id": "A", "text": "After lunch we went home."}, {"id": "B", "text": "After lunch, we went home."}, {"id": "C", "text": "After, lunch we went home."}, {"id": "D", "text": "After lunch we, went home."}]','B','The comma in choice B marks the end of the introductory phrase. Choice A omits the comma, and choices C and D split phrases incorrectly.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('ENGLISH','Pronouns','Choose the correct sentence.','[{"id": "A", "text": "Each student must bring their own pencil."}, {"id": "B", "text": "Each student must brings a pencil."}, {"id": "C", "text": "Each student must bringing a pencil."}, {"id": "D", "text": "Each student must brought a pencil."}]','A','The modal must takes the base form bring.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('ENGLISH','Concision','Which revision is most concise without changing the meaning of “At this point in time, we are ready”?','[{"id": "A", "text": "We are ready now."}, {"id": "B", "text": "Ready at this point."}, {"id": "C", "text": "We are currently at this time ready."}, {"id": "D", "text": "We at this point are ready now."}]','A','We are ready now expresses the meaning directly.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('READING','Main idea','Passage: “Urban trees cool streets, absorb rainwater, and provide shade. Cities that plant trees can improve residents’ comfort.” What is the main idea?','[{"id": "A", "text": "Trees only absorb rain."}, {"id": "B", "text": "Planting urban trees has multiple benefits."}, {"id": "C", "text": "All cities already have enough trees."}, {"id": "D", "text": "Trees prevent all flooding."}]','B','The passage lists several benefits of urban trees.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('READING','Inference','Passage: “Maya checked the forecast, packed an umbrella, and left early.” Which inference is best supported?','[{"id": "A", "text": "Maya expected possible rain."}, {"id": "B", "text": "Maya disliked umbrellas."}, {"id": "C", "text": "Maya missed the bus."}, {"id": "D", "text": "Maya was traveling abroad."}]','A','Checking weather and packing an umbrella suggest concern about rain.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('READING','Vocabulary in context','Passage: “The scientist gave a concise summary of the findings.” Concise most nearly means:','[{"id": "A", "text": "Lengthy"}, {"id": "B", "text": "Brief"}, {"id": "C", "text": "Uncertain"}, {"id": "D", "text": "Confusing"}]','B','Concise means brief and clear.','verified');
insert into public.questions(subject,topic,prompt,options,correct_answer,explanation,status) values ('READING','Evidence','Passage: “The library extended its hours after surveys showed students needed evening study space.” Why were the hours extended?','[{"id": "A", "text": "To reduce staffing"}, {"id": "B", "text": "Because of student survey responses"}, {"id": "C", "text": "To close earlier"}, {"id": "D", "text": "Because books were missing"}]','B','The passage explicitly links the change to survey findings.','verified');
